            this.refreshAllRows();
        } else {
            // Order not found - enable manual mode
            this.orderLoaded = false;
            this.products = [];
            this.showOrderStatus('warning', result.error || 'Order not found');
            this.showToast(result.error || 'Order not found. You can enter details manually.', 'warning');
