/**
 * Names & Numbers Roster Styles
 */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --names-numbers-cyan: #93c5fd;
    --names-numbers-magenta: #f9a8d4;
    --names-numbers-red: #9d174d;
    --nn-primary: var(--blue-600);
    --nn-primary-dark: var(--color-floor-dark);
    --nn-primary-light: var(--color-floor-light);
    --nn-bg: var(--color-bradley-tint);
    --nn-card-bg: var(--color-surface);
    --nn-border: var(--gray-200);
    --nn-text: var(--gray-800);
    --nn-text-secondary: var(--gray-500);
    --nn-hover-bg: var(--gray-100);
    --nn-success-bg: var(--emerald-100);
    --nn-success-text: var(--emerald-800);
    --nn-warning-bg: var(--amber-100);
    --nn-warning-text: var(--amber-800);
    --nn-error-bg: var(--red-100);
    --nn-error-text: var(--red-800);
    --nn-focus-shadow: 0 0 0 0.25rem rgb(37 99 235 / 25%);
}
/* stylelint-enable color-no-hex */

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    font-family: Inter, -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--nn-bg);
    color: var(--nn-text);
    line-height: 1.6;
    min-height: 100vh;
}

/* ============================================
   HEADER
   ============================================ */
.header {
    background: var(--nn-card-bg);
    border-bottom: 1px solid var(--nn-border);
    padding: 1rem 0;
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 1px 3px rgb(0 0 0 / 5%);
}

.header-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 2rem;
}

.header-left { display: flex; align-items: center; gap: 1.5rem; }
.logo { height: 40px; width: auto; }

.breadcrumb {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.875rem;
    color: var(--nn-text-secondary);
}
.breadcrumb a { color: var(--nn-primary); text-decoration: none; }
.breadcrumb a:hover { text-decoration: underline; }
.breadcrumb #breadcrumbCurrent { color: var(--nn-text); font-weight: 500; }

/* Action bar at the bottom of the form */
.action-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-top: 1rem;
}

.action-bar-group {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.header-right { display: flex; align-items: center; gap: 1rem; }
.current-date { font-size: 0.875rem; color: var(--nn-text-secondary); }

/* ============================================
   MAIN CONTAINER
   ============================================ */
.main-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 1.5rem 2rem;
}

/* Page band — shop-floor BLUE so the page reads as personalization the moment it
   opens (2026-09-04, Erik's colour code: Names & Numbers + Monogram = the same blue
   as their staff-dashboard tiles). Buttons and links already used --nn-primary;
   this gives the page a blue identity above the fold, like the Monogram dashboard. */
.header { border-top: 4px solid var(--nn-primary); }

.page-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1.25rem 1.5rem;
    border-radius: 0.75rem;
    color: var(--color-on-brand);
    background: linear-gradient(135deg, var(--nn-primary-dark) 0%, var(--nn-primary) 60%, var(--nn-primary-light) 100%);
    box-shadow: 0 10px 24px -12px rgb(37 99 235 / 60%);
}

.page-title {
    font-size: 1.5rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: var(--color-on-brand);
}
.page-title i { color: rgb(255 255 255 / 85%); }
.page-subtitle { font-size: 0.875rem; color: rgb(255 255 255 / 82%); margin-top: 0.25rem; }

.page-header-actions { display: flex; gap: 0.5rem; }

/* ============================================
   BUTTONS
   ============================================ */
.btn-primary {
    background: var(--nn-primary);
    color: var(--color-on-brand);
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.5rem;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    transition: background 0.15s;
}
.btn-primary:hover { background: var(--nn-primary-dark); }

.btn-secondary {
    background: var(--nn-card-bg);
    color: var(--nn-text);
    border: 1px solid var(--nn-border);
    padding: 0.5rem 1.25rem;
    border-radius: 0.5rem;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    text-decoration: none;
    transition: background 0.15s;
}
.btn-secondary:hover { background: var(--nn-hover-bg); }

.btn-success {
    background: var(--emerald-600);
    color: var(--color-on-brand);
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.5rem;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
}
.btn-success:hover { background: var(--emerald-700); }

.btn-danger {
    background: var(--red-600);
