.tab-btn:hover { color: var(--nn-text); background: var(--nn-hover-bg); }
.tab-btn.active { color: var(--nn-primary); border-bottom-color: var(--nn-primary); font-weight: 600; }

.tab-badge {
    background: var(--nn-primary);
