.tab-add-btn {
    background: none;
    border: 1px dashed var(--nn-border);
    padding: 0.4rem 1rem;
    font-size: 0.8rem;
    color: var(--nn-text-secondary);
    cursor: pointer;
    border-radius: 0.375rem;
    margin-left: 0.5rem;
    display: flex;
    align-items: center;
    gap: 0.4rem;
    align-self: center;
    margin-bottom: 2px;
}
.tab-add-btn:hover { border-color: var(--nn-primary); color: var(--nn-primary); }

/* ============================================
   GROUP CONFIG PANEL
   ============================================ */
.group-config {
    background: var(--slate-50);
    border: 1px solid var(--nn-border);
    border-radius: 0.5rem;
    padding: 1rem;
    margin-bottom: 1rem;
}

.group-config-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.group-config-title {
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--nn-text-secondary);
}

.config-section {
    margin-top: 1rem;
    padding-top: 1rem;
    border-top: 1px dashed var(--nn-border);
}
.config-section:first-child { border-top: none; padding-top: 0; margin-top: 0; }

.config-section > label {
    display: block;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--nn-text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    margin-bottom: 0.35rem;
}

.config-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.config-section-header label {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--nn-text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.config-section-hint {
    font-size: 0.75rem;
    color: var(--nn-text-secondary);
    margin-bottom: 0.6rem;
}

/* Garments editor */
.garments-editor { display: flex; flex-direction: column; gap: 0.6rem; }

.garment-row {
    background: var(--nn-card-bg);
    border: 1px solid var(--nn-border);
    border-radius: 0.5rem;
    padding: 0.6rem 0.75rem;
}

.garment-row-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.45rem;
}

.garment-row-idx {
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--nn-text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.garment-row-fields {
    display: grid;
    grid-template-columns: 1.4fr 1fr 1fr;
    gap: 0.5rem;
    margin-bottom: 0.45rem;
}

.garment-row-fields input {
    width: 100%;
    border: 1px solid var(--nn-border);
    border-radius: 0.375rem;
    padding: 0.4rem 0.6rem;
    font-size: 0.85rem;
    font-family: inherit;
}

.garment-row-fields input:focus {
    outline: none;
    border-color: var(--nn-primary);
    box-shadow: var(--nn-focus-shadow);
}

.garment-row-toggles {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.garment-row-toggles label {
    display: flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.78rem;
    padding: 0.2rem 0.45rem;
    background: var(--nn-bg);
    border: 1px solid var(--nn-border);
    border-radius: 0.3rem;
    cursor: pointer;
    color: var(--nn-text-secondary);
}

.garment-row-toggles label:has(input:checked) {
    border-color: var(--nn-primary);
    background: var(--color-floor-tint);
    color: var(--nn-primary-dark);
}
.garment-delete-btn:disabled { opacity: 0.3; cursor: not-allowed; }

/* Custom columns editor */
.custom-columns-editor { display: flex; flex-direction: column; gap: 0.4rem; }

.custom-cols-empty {
    font-size: 0.8rem;
    color: var(--nn-text-secondary);
    font-style: italic;
    padding: 0.4rem 0;
}

.custom-col-row {
    display: flex;
    gap: 0.4rem;
    align-items: center;
}

.custom-col-row .cc-label {
    flex: 1;
    border: 1px solid var(--nn-border);
    border-radius: 0.375rem;
    padding: 0.4rem 0.6rem;
    font-size: 0.85rem;
    font-family: inherit;
}

.custom-col-row .cc-label:focus {
    outline: none;
    border-color: var(--nn-primary);
    box-shadow: var(--nn-focus-shadow);
}

/* Person column picker (checkbox chips) */
.column-picker {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.column-picker label {
    display: flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.8rem;
    padding: 0.25rem 0.55rem;
    background: var(--nn-card-bg);
    border: 1px solid var(--nn-border);
    border-radius: 0.3rem;
    cursor: pointer;
}

.column-picker label:has(input:checked) {
    border-color: var(--nn-primary);
    background: var(--color-floor-tint);
    color: var(--nn-primary-dark);
}
.column-picker input[type="checkbox"] { accent-color: var(--nn-primary); }

/* ============================================
   IMPORT TOOLBAR
   ============================================ */
.import-toolbar {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

/* ============================================
   DATA TABLE
   ============================================ */
.roster-table-wrapper {
    overflow-x: auto;
    border: 1px solid var(--nn-border);
    border-radius: 0.5rem;
}

.roster-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.875rem;
}

.roster-table thead th {
    background: var(--slate-50);
    padding: 0.5rem 0.75rem;
    text-align: left;
    font-weight: 600;
    font-size: 0.8rem;
    color: var(--nn-text-secondary);
    text-transform: uppercase;
    letter-spacing: 0.03em;
    border-bottom: 2px solid var(--nn-border);
    white-space: nowrap;
    position: sticky;
    top: 0;
}

.roster-table tbody td {
    padding: 0.35rem 0.5rem;
    border-bottom: 1px solid var(--nn-border);
    vertical-align: middle;
}

.roster-table tbody tr:hover { background: var(--slate-50); }

.roster-table tbody td input {
    width: 100%;
    border: 1px solid transparent;
    padding: 0.3rem 0.5rem;
    font-size: 0.875rem;
    font-family: inherit;
    background: transparent;
    border-radius: 0.25rem;
    transition: border-color 0.15s;
}

.roster-table tbody td input:focus {
    border-color: var(--nn-primary);
    outline: none;
    background: var(--color-surface);
    box-shadow: var(--nn-focus-shadow);
}
.roster-table tbody td input:hover:not(:focus) { border-color: var(--nn-border); }

.roster-table .row-number {
    color: var(--nn-text-secondary);
    font-size: 0.8rem;
    text-align: center;
    width: 40px;
    font-weight: 500;
}

.roster-table .row-actions {
    width: 36px;
    text-align: center;
    position: sticky;
    right: 0;
    background: var(--nn-card-bg);
    box-shadow: -2px 0 4px rgb(0 0 0 / 5%);
}

.roster-table thead th.row-actions {
    position: sticky;
    right: 0;
    background: var(--slate-50);
    z-index: 2;
}

.row-delete-btn {
    background: none;
    border: none;
    color: var(--gray-300);
    cursor: pointer;
    padding: 0.25rem;
    border-radius: 0.25rem;
    font-size: 0.875rem;
}
.row-delete-btn:hover { color: var(--red-600); background: var(--nn-error-bg); }

.roster-table tfoot td {
    padding: 0.5rem 0.75rem;
    background: var(--slate-50);
    font-weight: 600;
    font-size: 0.8rem;
    color: var(--nn-text-secondary);
    border-top: 2px solid var(--nn-border);
}

/* Garment band colors — repeating 4-color palette for up to many garments */
.garment-band-0 { --band-bg: var(--color-floor-tint); --band-border: var(--names-numbers-cyan); --band-text: var(--blue-800); }
.garment-band-1 { --band-bg: var(--amber-100); --band-border: var(--amber-300); --band-text: var(--amber-800); }
.garment-band-2 { --band-bg: var(--store-green-100); --band-border: var(--green-300); --band-text: var(--print-green); }
.garment-band-3 { --band-bg: var(--red-50); --band-border: var(--names-numbers-magenta); --band-text: var(--names-numbers-red); }

.roster-table thead th.col-garment-band {
    background: var(--band-bg);
    color: var(--band-text);
    border-left: 2px solid var(--band-border);
    border-right: 2px solid var(--band-border);
    text-align: center;
    font-weight: 700;
    font-size: 0.85rem;
    text-transform: none;
    letter-spacing: 0;
    padding: 0.45rem 0.75rem;
}

.garment-band-style {
    font-weight: 500;
    font-size: 0.75rem;
    color: var(--nn-text-secondary);
    margin-left: 0.35rem;
}

.roster-table thead th.col-garment {
    background: color-mix(in srgb, var(--band-bg) 55%, var(--color-surface));
    border-left: 1px solid var(--band-border);
    border-right: 1px solid var(--band-border);
}

.roster-table tbody td.col-garment {
    background: color-mix(in srgb, var(--band-bg) 28%, var(--color-surface));
    border-left: 1px solid var(--band-border);
    border-right: 1px solid var(--band-border);
}

.roster-table tbody tr:hover td.col-garment {
    background: color-mix(in srgb, var(--band-bg) 45%, var(--color-surface));
}

/* Sticky row-number on horizontal scroll (person columns stay inline — multi-col sticky
   requires dynamic offset calculation that produces flicker on resize). */
@media (width >= 900px) {
    .roster-table thead th.row-number,
    .roster-table tbody td.row-number {
        position: sticky; left: 0;
        z-index: 2;
    }
    .roster-table thead th.row-number { background: var(--slate-50); z-index: 4; }
    .roster-table tbody td.row-number { background: var(--nn-card-bg); }
}

/* Size Breakdown Card */
.size-breakdown-card { margin-top: 1rem; }

.size-breakdown-body {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 0.85rem;
}

.breakdown-garment {
    background: var(--band-bg);
    border: 1px solid var(--band-border);
    border-radius: 0.5rem;
    padding: 0.75rem 0.9rem;
}

.breakdown-garment-header {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 0.5rem;
    padding-bottom: 0.5rem;
    margin-bottom: 0.45rem;
    border-bottom: 1px solid var(--band-border);
    color: var(--band-text);
}
.breakdown-garment-header strong { font-size: 1rem; }

.breakdown-garment-meta {
    font-size: 0.78rem;
    color: var(--nn-text-secondary);
}

.breakdown-garment-total {
    margin-left: auto;
    font-size: 0.85rem;
    font-weight: 600;
}

.breakdown-size-list {
    list-style: none;
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 0.15rem 1rem;
    font-size: 0.88rem;
}

.breakdown-size-list li {
    display: contents;
}
.breakdown-size { color: var(--nn-text); }

.breakdown-count {
    font-weight: 600;
    color: var(--band-text);
    text-align: right;
}

/* OCR multi-garment preview */
.ocr-garments-preview {
    margin-top: 1rem;
    padding: 0.75rem;
    background: var(--slate-50);
    border: 1px solid var(--nn-border);
    border-radius: 0.5rem;
}

.ocr-garments-label, .ocr-entries-label {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--nn-text-secondary);
    margin-bottom: 0.5rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

#ocrGarmentsList {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.ocr-garment-chip {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.35rem 0.5rem;
    background: var(--nn-card-bg);
    border: 1px solid var(--nn-border);
    border-radius: 0.375rem;
}

.ocr-garment-chip .ocr-garment-label {
    flex: 1;
    border: 1px solid var(--nn-border);
    border-radius: 0.25rem;
    padding: 0.3rem 0.5rem;
    font-size: 0.85rem;
    font-family: inherit;
}

.ocr-garment-chip .ocr-garment-label:focus {
    outline: none;
    border-color: var(--nn-primary);
    box-shadow: var(--nn-focus-shadow);
}

.ocr-garment-chip label {
    display: flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.78rem;
    color: var(--nn-text-secondary);
    white-space: nowrap;
}

.ocr-garment-remove {
    background: none;
    border: 1px solid var(--nn-border);
    width: 26px; height: 26px;
    border-radius: 0.25rem;
    color: var(--nn-text-secondary);
    cursor: pointer;
}
.ocr-garment-remove:hover { color: var(--red-600); border-color: var(--red-600); }
.ocr-garment-remove:disabled { opacity: 0.3; cursor: not-allowed; }
.ocr-entries-preview { margin-top: 1rem; }

/* ============================================
   IMPORT MODALS
   ============================================ */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgb(0 0 0 / 40%);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    opacity: 0;
    visibility: hidden;
    transition: all 0.2s;
}
.modal-overlay.active { opacity: 1; visibility: visible; }

.modal {
    background: var(--nn-card-bg);
    border-radius: 0.75rem;
    padding: 1.5rem;
    max-width: 600px;
    width: 90%;
    max-height: 80vh;
    overflow-y: auto;
    box-shadow: 0 20px 60px rgb(0 0 0 / 15%);
    transform: translateY(20px);
    transition: transform 0.2s;
}
.modal-overlay.active .modal { transform: translateY(0); }

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.modal-title { font-size: 1.1rem; font-weight: 600; }

.modal-close {
    background: none;
    border: none;
    font-size: 1.25rem;
    color: var(--nn-text-secondary);
    cursor: pointer;
    padding: 0.25rem;
}
.modal-close:hover { color: var(--nn-text); }

.modal-body textarea {
    width: 100%;
    min-height: 150px;
    border: 1px solid var(--nn-border);
    border-radius: 0.5rem;
    padding: 0.75rem;
    font-family: inherit;
    font-size: 0.875rem;
    resize: vertical;
}

.modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    margin-top: 1rem;
}

/* ============================================
   OCR DROP ZONE
   ============================================ */
.ocr-drop-zone {
    border: 2px dashed var(--nn-border);
    border-radius: 0.75rem;
    padding: 2rem;
    text-align: center;
    cursor: pointer;
    transition: all 0.2s;
    background: var(--gray-50);
}

.ocr-drop-zone:hover,
.ocr-drop-zone.dragover {
    border-color: var(--nn-primary);
    background: var(--color-floor-tint);
}

.ocr-drop-zone i {
    font-size: 2.5rem;
    color: var(--nn-primary);
    margin-bottom: 0.75rem;
}

.ocr-drop-zone p {
    color: var(--nn-text-secondary);
    font-size: 0.875rem;
}

.ocr-preview img {
    max-width: 100%;
    max-height: 200px;
    border-radius: 0.5rem;
    margin-top: 1rem;
    border: 1px solid var(--nn-border);
}

.ocr-pdf-chip {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.85rem 1rem;
    margin-top: 1rem;
    background: var(--red-50);
    border: 1px solid var(--red-300);
    border-radius: 0.5rem;
    color: var(--red-800);
}

.ocr-pdf-chip i {
    font-size: 2rem;
    color: var(--red-600);
    margin: 0;
}
.ocr-pdf-chip strong { font-size: 0.95rem; word-break: break-all; }

.ocr-pdf-meta {
    font-size: 0.8rem;
    color: var(--nn-text-secondary);
    margin-top: 0.15rem;
}

.ocr-processing {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem;
    background: var(--color-floor-tint);
    border-radius: 0.5rem;
    color: var(--nn-primary);
    font-weight: 500;
}

.spinner {
    width: 20px;
    height: 20px;
    border: 2px solid var(--nn-border);
    border-top-color: var(--nn-primary);
    border-radius: 50%;
    animation: spin 0.6s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

/* ============================================
   STATUS BADGES
   ============================================ */
.status-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.2rem 0.6rem;
    border-radius: 99px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.status-draft { background: var(--gray-200); color: var(--gray-600); }
.status-submitted { background: var(--sky-100); color: var(--blue-800); }
.status-in-production { background: var(--nn-warning-bg); color: var(--nn-warning-text); }
.status-completed { background: var(--nn-success-bg); color: var(--nn-success-text); }

/* ============================================
   TOAST NOTIFICATION
   ============================================ */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background: var(--gray-800);
    color: var(--color-on-brand);
    padding: 0.75rem 1.25rem;
    border-radius: 0.5rem;
    font-size: 0.875rem;
    z-index: 2000;
    transform: translateY(100px);
    opacity: 0;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    box-shadow: 0 10px 30px rgb(0 0 0 / 20%);
}
.toast.show { transform: translateY(0); opacity: 1; }
.toast.success { background: var(--emerald-600); }
.toast.error { background: var(--red-600); }

/* ============================================
   SEARCH PANEL
   ============================================ */
.search-panel {
    background: var(--nn-card-bg);
    border: 1px solid var(--nn-border);
    border-radius: 0.75rem;
    padding: 1rem 1.5rem;
    margin-bottom: 1rem;
    box-shadow: 0 2px 8px rgb(0 0 0 / 6%);
}

.search-row {
    display: flex;
    gap: 0.75rem;
    align-items: end;
}

.search-row input {
    flex: 1;
    border: 1px solid var(--nn-border);
    border-radius: 0.375rem;
    padding: 0.5rem 0.75rem;
    font-size: 0.875rem;
    font-family: inherit;
}

.search-row input:focus {
    outline: none;
    border-color: var(--nn-primary);
    box-shadow: var(--nn-focus-shadow);
}

/* ============================================
   EMPTY STATE
   ============================================ */
.empty-state {
    text-align: center;
    padding: 3rem 2rem;
    color: var(--nn-text-secondary);
}

.empty-state i {
    font-size: 3rem;
    margin-bottom: 1rem;
    color: var(--gray-300);
}
.empty-state h3 { color: var(--nn-text); margin-bottom: 0.5rem; }

/* ============================================
   PRINT STYLES
   ============================================ */
@media print {
    .header, .page-header-actions, .import-toolbar,
    .group-config, .tab-add-btn, .row-delete-btn,
    .btn-primary, .btn-secondary, .btn-success, .btn-danger, .btn-sm, .btn-icon,
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    .toast, .search-panel, .modal-overlay { display: none !important; }

    body { background: var(--color-surface); }
    .main-container { max-width: 100%; padding: 0; }
    .card { border: none; box-shadow: none; padding: 0; margin-bottom: 0.5rem; }

    .roster-table { font-size: 11px; }
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    .roster-table thead th { background: var(--brand-100) !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }

    .roster-table tbody td.col-garment,
    .roster-table thead th.col-garment,
    .roster-table thead th.col-garment-band,
    .breakdown-garment {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }

    .roster-table tbody td input {
        border: none;
        background: transparent;
        padding: 0.15rem 0.35rem;
    }
    .tab-bar { display: none; }

    .size-breakdown-card { break-inside: avoid; margin-top: 0.75rem; }

    .size-breakdown-body {
        grid-template-columns: repeat(3, 1fr);
        gap: 0.5rem;
    }
    .breakdown-garment { padding: 0.4rem 0.6rem; font-size: 10px; }
    .breakdown-garment-header strong { font-size: 11px; }
    .breakdown-size-list { font-size: 10px; }
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (width <= 768px) {
    .header-container { padding: 0 1rem; }
    .main-container { padding: 1rem; }
    .form-row { grid-template-columns: 1fr; }
    .page-header { flex-direction: column; align-items: flex-start; gap: 1rem; }
    .import-toolbar { flex-direction: column; }
}

/* Phone (≤640px) — 2026-09-05 staff-dashboard sweep: the page measured wider than the
   viewport at 375px and panned sideways. */
@media (width <= 640px) {
    .header-right { flex-wrap: wrap; row-gap: 6px; }
}

@media (width <= 640px) {
    .page-header { flex-wrap: wrap; row-gap: .5rem; }
}

@media (width <= 640px) {
    .header-container { flex-wrap: wrap; row-gap: .5rem; }
}

/* stylelint-disable no-duplicate-selectors -- legacy sheet: rules were appended over time; merging them would reorder the cascade (2026-09-07) */

/**
 * Monogram Form Styles
 * Styling for the monogram/personalization tracking form
 */

/* ============================================
   CSS VARIABLES
   ============================================ */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --monogram-form-gray-dark: #000;
    --monogram-form-cyan-dark: #1a3a5c;
    --monogram-form-gray: #666;
    --monogram-form-cyan: #4a90a4;
    --monogram-form-yellow: #f0d78c;
    --monogram-form-yellow-2: #8a6d00;
    --monogram-form-yellow-3: #a88400;
    --monogram-form-yellow-4: #e0d4a8;
    --monogram-form-yellow-dark: #5a4a00;
    --monogram-form-yellow-5: #e5c66d;
    --monogram-form-gray-dark-2: #333;
    --primary-color: var(--brand-mid);
    --primary-dark: var(--print-green);
    --primary-light: var(--brand-500);
    --bg-color: var(--color-bradley-tint);
    --card-bg: var(--color-surface);
    --border-color: var(--gray-200);
    --text-primary: var(--gray-800);
    --text-secondary: var(--gray-500);
    --hover-bg: var(--gray-100);
    --success-bg: var(--emerald-100);
    --success-text: var(--emerald-800);
    --warning-bg: var(--amber-100);
    --warning-text: var(--amber-800);
    --error-bg: var(--red-100);
    --error-text: var(--red-800);
    --focus-shadow: 0 0 0 0.25rem rgb(58 124 82 / 25%);
}
/* stylelint-enable color-no-hex */

/* ============================================
   BASE STYLES
   ============================================ */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Inter, -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--bg-color);
    color: var(--text-primary);
    line-height: 1.6;
    min-height: 100vh;
}

/* ============================================
   HEADER
   ============================================ */
.header {
    background: var(--card-bg);
    border-bottom: 1px solid var(--border-color);
    padding: 1rem 0;
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 1px 3px rgb(0 0 0 / 5%);
}

.header-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 2rem;
}

.header-left {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.logo {
    height: 40px;
    width: auto;
}

.breadcrumb {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: var(--text-secondary);
    font-size: 0.875rem;
}

.breadcrumb a {
    color: var(--primary-color);
    text-decoration: none;
    font-weight: 500;
    transition: color 0.2s;
}

.breadcrumb a:hover {
    color: var(--primary-dark);
}

.header-right {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.current-date {
    color: var(--text-secondary);
    font-size: 0.875rem;
}

/* ============================================
   BUTTONS
   ============================================ */
.btn-primary {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.625rem 1.25rem;
    background: var(--primary-color);
    color: white;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-primary:hover {
    background: var(--primary-dark);
    transform: translateY(-1px);
    box-shadow: 0 4px 8px rgb(58 124 82 / 30%);
}

.btn-secondary {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.625rem 1.25rem;
    background: var(--card-bg);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
    border-radius: 0.375rem;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
    text-decoration: none;
}

.btn-secondary:hover {
    background: var(--hover-bg);
    border-color: var(--primary-color);
}

.btn-sm {
    padding: 0.375rem 0.75rem;
    font-size: 0.8125rem;
}

.btn-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    background: var(--card-bg);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
    border-radius: 0.375rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-icon:hover {
    background: var(--primary-color);
    color: white;
    border-color: var(--primary-color);
}

.btn-lookup {
    padding: 0.5rem 1rem;
    background: var(--primary-color);
    color: white;
    border: none;
    border-radius: 0 0.375rem 0.375rem 0;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
    white-space: nowrap;
}

.btn-lookup:hover {
    background: var(--primary-dark);
}

.btn-close {
    background: none;
    border: none;
    font-size: 1.5rem;
    color: var(--text-secondary);
    cursor: pointer;
    padding: 0;
    line-height: 1;
}

.btn-close:hover {
    color: var(--text-primary);
}

/* ============================================
   MAIN CONTAINER
   ============================================ */
.main-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 2rem;
}

/* ============================================
   PAGE HEADER
   ============================================ */
.page-header {
    background: linear-gradient(135deg, var(--primary-color), var(--primary-dark));
    color: white;
    padding: 1.5rem 2rem;
    border-radius: 0.75rem;
    margin-bottom: 1.5rem;
    box-shadow: 0 4px 12px rgb(58 124 82 / 30%);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.page-title {
    font-size: 1.75rem;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 0.25rem;
}

.page-subtitle {
    font-size: 0.9rem;
    opacity: 0.9;
}

.page-header-actions {
    display: flex;
    gap: 0.5rem;
}

.page-header-actions .btn-icon {
    background: rgb(255 255 255 / 20%);
    border-color: rgb(255 255 255 / 30%);
    color: white;
}

.page-header-actions .btn-icon:hover {
    background: white;
    color: var(--primary-color);
}

/* ============================================
   SEARCH PANEL
   ============================================ */
.search-panel {
    background: var(--card-bg);
    border-radius: 0.75rem;
    margin-bottom: 1.5rem;
    box-shadow: 0 2px 8px rgb(0 0 0 / 8%);
    overflow: hidden;
}

.search-panel-header {
    background: var(--hover-bg);
    padding: 1rem 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--border-color);
}

.search-panel-header h3 {
    font-size: 1rem;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.search-panel-body {
    padding: 1.5rem;
}

.search-inputs {
    display: flex;
    gap: 1rem;
    align-items: flex-end;
    flex-wrap: wrap;
}

.search-field {
    flex: 1;
    min-width: 200px;
}

.search-field label {
    display: block;
    font-size: 0.8125rem;
    font-weight: 500;
    color: var(--text-secondary);
    margin-bottom: 0.375rem;
}

.search-field input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--border-color);
    border-radius: 0.375rem;
    font-size: 0.875rem;
}

.search-results {
    margin-top: 1.5rem;
    border-top: 1px solid var(--border-color);
    padding-top: 1.5rem;
}

.search-results:empty {
    display: none;
}

.search-result-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: var(--hover-bg);
    border-radius: 0.375rem;
    margin-bottom: 0.5rem;
}

.search-result-item:last-child {
    margin-bottom: 0;
}

.search-result-info {
    display: flex;
    gap: 2rem;
}

.search-result-info span {
    font-size: 0.875rem;
}

.search-result-actions {
    display: flex;
    gap: 0.5rem;
}

/* ============================================
   FORM CONTAINER
   ============================================ */
.form-container {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

/* ============================================
   FORM SECTIONS
   ============================================ */
.form-section {
    background: var(--card-bg);
    border-radius: 0.75rem;
    padding: 1.5rem;
    box-shadow: 0 2px 8px rgb(0 0 0 / 8%);
}

.section-title {
    font-size: 1.125rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 1.25rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 2px solid var(--border-color);
}

.section-title i {
    color: var(--primary-color);
}

.section-header-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.section-header-row .section-title {
    margin-bottom: 0;
    padding-bottom: 0;
    border-bottom: none;
}

.section-actions {
    display: flex;
    gap: 0.5rem;
}

.name-count {
    font-size: 0.875rem;
    font-weight: 400;
    color: var(--text-secondary);
    margin-left: 0.5rem;
}

/* ============================================
   FORM FIELDS
   ============================================ */
.form-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1.25rem;
}

.form-group {
    display: flex;
    flex-direction: column;
}

.form-group.full-width {
    grid-column: 1 / -1;
}

.form-group label {
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--text-primary);
    margin-bottom: 0.375rem;
}

.form-group .required {
    color: var(--bs-danger);
}

.form-group input,
.form-group textarea,
.form-group select {
    padding: 0.625rem 0.875rem;
    border: 1px solid var(--border-color);
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    font-family: inherit;
    transition: border-color 0.2s, box-shadow 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: var(--focus-shadow);
}

.form-group textarea {
    resize: vertical;
    min-height: 80px;
}

.field-hint {
    font-size: 0.75rem;
    color: var(--text-secondary);
    margin-top: 0.25rem;
}

.input-with-button {
    display: flex;
}

.input-with-button input {
    flex: 1;
    border-radius: 0.375rem 0 0 0.375rem;
    border-right: none;
}

.input-with-button input:focus {
    z-index: 1;
}

/* ============================================
   THREAD COLOR SELECTOR
   ============================================ */
.thread-color-group {
    position: relative;
}

.thread-color-selector {
    position: relative;
}

.thread-color-toggle {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.625rem 0.875rem;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    font-family: inherit;
    color: var(--text-primary);
    cursor: pointer;
    transition: border-color 0.2s, box-shadow 0.2s;
    text-align: left;
}

.thread-color-toggle:hover {
    border-color: var(--primary-color);
}

.thread-color-toggle:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: var(--focus-shadow);
}

.thread-color-toggle i {
    color: var(--text-secondary);
    transition: transform 0.2s;
}

.thread-color-toggle.open i {
    transform: rotate(180deg);
}

.thread-color-dropdown {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    margin-top: 4px;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: 0.375rem;
    box-shadow: 0 4px 12px rgb(0 0 0 / 15%);
    z-index: 1000;
    max-height: 300px;
    display: flex;
    flex-direction: column;
}

.thread-color-dropdown[hidden] {
    display: none;
}

.thread-color-search {
    padding: 0.5rem;
    border-bottom: 1px solid var(--border-color);
}

.thread-color-search input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--border-color);
    border-radius: 0.25rem;
    font-size: 0.875rem;
}

.thread-color-search input:focus {
    outline: none;
    border-color: var(--primary-color);
}

.thread-color-list {
    overflow-y: auto;
    max-height: 240px;
    padding: 0.25rem 0;
}

.thread-color-option {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    cursor: pointer;
    transition: background 0.15s;
}

.thread-color-option:hover {
    background: var(--hover-bg);
}

.thread-color-option input[type="checkbox"] {
    width: 16px;
    height: 16px;
    margin: 0;
    accent-color: var(--primary-color);
}

.thread-color-option label {
    flex: 1;
    font-size: 0.875rem;
    cursor: pointer;
    margin: 0;
}

.thread-color-option .thread-number {
    font-size: 0.75rem;
    color: var(--text-secondary);
    font-family: monospace;
}

/* Done button at bottom of dropdown */
.thread-color-actions {
    padding: 0.5rem;
    border-top: 1px solid var(--border-color);
    display: flex;
    justify-content: flex-end;
}

.thread-color-actions .btn-primary {
    padding: 0.375rem 1rem;
}

/* Selected thread colors tags */
.selected-thread-colors {
    display: flex;
    flex-wrap: wrap;
    gap: 0.375rem;
    margin-top: 0.5rem;
}

.selected-thread-colors:empty {
    display: none;
}

.thread-color-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    padding: 0.25rem 0.5rem;
    background: var(--primary-color);
    color: white;
    border-radius: 1rem;
    font-size: 0.8125rem;
    font-weight: 500;
}

.thread-color-tag .remove-tag {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px;
    height: 16px;
    background: rgb(255 255 255 / 20%);
    border: none;
    border-radius: 50%;
    color: white;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 0;
    line-height: 1;
}

.thread-color-tag .remove-tag:hover {
    background: rgb(255 255 255 / 40%);
}

/* ============================================
   LOCATION SELECTOR
   ============================================ */
.location-group {
    position: relative;
}

.location-selector {
    position: relative;
}

.location-toggle {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.625rem 0.875rem;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    font-family: inherit;
    color: var(--text-primary);
    cursor: pointer;
    transition: border-color 0.2s, box-shadow 0.2s;
    text-align: left;
}

.location-toggle:hover {
    border-color: var(--primary-color);
}

.location-toggle:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: var(--focus-shadow);
}

.location-toggle i {
    color: var(--text-secondary);
    transition: transform 0.2s;
}

.location-toggle.open i {
    transform: rotate(180deg);
}

.location-dropdown {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    margin-top: 4px;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: 0.375rem;
    box-shadow: 0 4px 12px rgb(0 0 0 / 15%);
    z-index: 1000;
    max-height: 300px;
    display: flex;
    flex-direction: column;
}

.location-dropdown[hidden] {
    display: none;
}

.location-list {
    overflow-y: auto;
    max-height: 200px;
    padding: 0.25rem 0;
}

.location-option {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    cursor: pointer;
    transition: background 0.15s;
}

.location-option:hover {
    background: var(--hover-bg);
}

.location-option input[type="checkbox"] {
    width: 16px;
    height: 16px;
    margin: 0;
    accent-color: var(--primary-color);
}

.location-option label {
    flex: 1;
    font-size: 0.875rem;
    cursor: pointer;
    margin: 0;
}

.location-other-input {
    padding: 0.5rem 0.75rem;
    border-top: 1px solid var(--border-color);
}

.location-other-input input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--border-color);
    border-radius: 0.25rem;
    font-size: 0.875rem;
}

.location-other-input input:focus {
    outline: none;
    border-color: var(--primary-color);
}

.location-actions {
    padding: 0.5rem;
    border-top: 1px solid var(--border-color);
    display: flex;
    justify-content: flex-end;
}

.location-actions .btn-primary {
    padding: 0.375rem 1rem;
}

/* Selected locations tags */
.selected-locations {
    display: flex;
    flex-wrap: wrap;
    gap: 0.375rem;
    margin-top: 0.5rem;
}

.selected-locations:empty {
    display: none;
}

.location-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    padding: 0.25rem 0.5rem;
    background: var(--monogram-form-cyan);
    color: white;
    border-radius: 1rem;
    font-size: 0.8125rem;
    font-weight: 500;
}

.location-tag .remove-tag {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px;
    height: 16px;
    background: rgb(255 255 255 / 20%);
    border: none;
    border-radius: 50%;
    color: white;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 0;
    line-height: 1;
}

.location-tag .remove-tag:hover {
    background: rgb(255 255 255 / 40%);
}

/* ============================================
   PASTE NAMES (BULK IMPORT)
   ============================================ */
.paste-names-group {
    margin-top: 1rem;
}

.paste-names-container {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.paste-names-textarea {
    width: 100%;
    padding: 0.625rem 0.875rem;
    border: 1px solid var(--border-color);
    border-radius: 0.375rem;
    font-size: 0.875rem;
    font-family: inherit;
    resize: vertical;
    min-height: 80px;
}

.paste-names-textarea:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: var(--focus-shadow);
}

.paste-names-actions {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.imported-count {
    font-size: 0.875rem;
    color: var(--text-secondary);
    margin-left: auto;
}

/* Unassigned Names Panel */
.unassigned-names-panel {
    margin-top: 0.75rem;
    padding: 0.75rem;
    background: var(--store-rush-soft);
    border: 1px solid var(--monogram-form-yellow);
    border-radius: 0.375rem;
}

.unassigned-header {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.5rem;
    color: var(--monogram-form-yellow-2);
}

.unassigned-count {
    font-weight: normal;
    color: var(--monogram-form-yellow-3);
}

.unassigned-list {
    display: flex;
    flex-wrap: wrap;
    gap: 0.375rem;
}

.unassigned-name-tag {
    display: inline-block;
    padding: 0.25rem 0.5rem;
    background: white;
    border: 1px solid var(--monogram-form-yellow-4);
    border-radius: 0.25rem;
    font-size: 0.8125rem;
    color: var(--monogram-form-yellow-dark);
}

.all-assigned {
    color: var(--success-color);
    font-weight: 500;
}

/* Name cell with dropdown + input - use wrapper div for flex to avoid table layout issues */
.cell-name .cell-content {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.name-dropdown {
    width: 100%;
    padding: 4px 6px;
    font-size: 0.75rem;
}

/* ============================================
   ORDER STATUS
   ============================================ */
.order-status {
    margin-top: 1rem;
}

.status-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    font-weight: 500;
}

.status-loading {
    background: var(--hover-bg);
    color: var(--text-secondary);
}

.status-success {
    background: var(--success-bg);
    color: var(--success-text);
}

.status-error {
    background: var(--error-bg);
    color: var(--error-text);
}

.status-warning {
    background: var(--warning-bg);
    color: var(--warning-text);
}

/* ============================================
   NAMES TABLE
   ============================================ */
.table-container {
    overflow-x: auto;
    margin: 0 -0.5rem;
    padding: 0 0.5rem;
}

.names-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.875rem;
}

.names-table th {
    background: var(--hover-bg);
    padding: 0.75rem 0.5rem;
    text-align: left;
    font-weight: 600;
    color: var(--text-primary);
    border-bottom: 2px solid var(--border-color);
    white-space: nowrap;
}

.names-table td {
    padding: 0.5rem;
    border-bottom: 1px solid var(--border-color);
    vertical-align: middle;
}

.names-table tbody tr:hover {
    background: var(--hover-bg);
}

/* Column widths */
.col-num { width: 40px; text-align: center; }
.col-style { width: 120px; }
.col-desc { width: 180px; }
.col-color { width: 110px; }
.col-size { width: 80px; }
.col-thread-location { width: 160px; }
.col-name { min-width: 140px; }
.col-action { width: 40px; text-align: center; }

/* Stacked Thread/Location cell - use wrapper div for flex to avoid table layout issues */
.cell-thread-location .cell-content {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.cell-thread-location .cell-content select {
    width: 100%;
    padding: 4px 6px;
    font-size: 0.75rem;
}

/* Table inputs */
.names-table input,
.names-table select {
    width: 100%;
    padding: 0.375rem 0.5rem;
    border: 1px solid var(--border-color);
    border-radius: 0.25rem;
    font-size: 0.8125rem;
    font-family: inherit;
}

.names-table input:focus,
.names-table select:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: 0 0 0 2px rgb(58 124 82 / 15%);
}

.names-table .row-number {
    font-weight: 600;
    color: var(--text-secondary);
}

.names-table .input-readonly {
    background: var(--hover-bg);
    color: var(--text-secondary);
}

/* Manual entry mode styling */
.names-table .manual-entry {
    background: var(--store-paper);  /* Subtle warm tint to indicate manual entry */
    border-color: var(--monogram-form-yellow-5);
}

.names-table .manual-entry:focus {
    border-color: var(--primary-color);
    background: var(--card-bg);
}

/* Fields that need user input (e.g., null color from API) */
.names-table .needs-input {
    border-color: var(--amber-500);
    background: var(--store-paper);
}

.names-table .needs-input::placeholder {
    color: var(--amber-700);
}

/* Delete row button */
.btn-delete-row {
    width: 28px;
    height: 28px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: transparent;
    border: 1px solid transparent;
    border-radius: 0.25rem;
    color: var(--text-secondary);
    cursor: pointer;
    transition: all 0.2s;
}

.btn-delete-row:hover {
    background: var(--error-bg);
    border-color: var(--bs-danger);
}

.table-footer {
    margin-top: 1rem;
    display: flex;
    justify-content: center;
}

/* ============================================
   FORM ACTIONS
   ============================================ */
.form-actions {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: var(--card-bg);
    border-radius: 0.75rem;
    padding: 1.25rem 1.5rem;
    box-shadow: 0 2px 8px rgb(0 0 0 / 8%);
}

.actions-left,
.actions-right {
    display: flex;
    gap: 0.75rem;
}

/* ============================================
   PRINT STYLES
   ============================================ */
.print-template {
    display: none;
}

@media print {
    /* Hide everything except print template */
    body * {
        visibility: hidden;
    }

    .print-template,
    .print-template * {
        visibility: visible;
    }

    .print-template {
        display: block;
        position: absolute;
        left: 0;
        top: 0;
        width: 100%;
        padding: 20px;
        background: white;
    }

    .header,
    .main-container,
    .loading-overlay,
    .toast-container {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        display: none !important;
    }

    /* Print header */
    .print-header {
        display: flex;
        justify-content: space-between;
        align-items: flex-start;
        margin-bottom: 20px;
        padding-bottom: 15px;
        border-bottom: 2px solid var(--monogram-form-cyan-dark);
    }

    .print-logo {
        height: 50px;
        width: auto;
    }

    .print-header-right {
        text-align: right;
    }

    .print-date {
        font-size: 12px;
        color: var(--monogram-form-gray);
    }

    .print-title {
        font-size: 24px;
        color: var(--monogram-form-cyan-dark);
        margin-top: 5px;
    }

    /* Print order info */
    .print-order-info {
        display: flex;
        gap: 40px;
        margin-bottom: 20px;
        padding: 15px;
        background: var(--color-bradley-tint);
        border-radius: 5px;
    }

    .print-field strong {
        display: block;
        font-size: 11px;
        color: var(--monogram-form-gray);
        margin-bottom: 3px;
    }

    .print-field span {
        font-size: 14px;
        font-weight: 600;
    }

    /* Print monogram details */
    .print-monogram-details {
        margin-bottom: 20px;
    }

    .print-monogram-details h3 {
        font-size: 14px;
        color: var(--monogram-form-cyan-dark);
        margin-bottom: 10px;
        padding-bottom: 5px;
        border-bottom: 1px solid var(--store-line);
    }

    .print-detail-row {
        display: flex;
        gap: 40px;
        margin-bottom: 10px;
    }

    .print-notes {
        margin-top: 10px;
    }

    .print-notes p {
        background: var(--color-bradley-tint);
        padding: 10px;
        border-radius: 5px;
        font-size: 13px;
        margin-top: 5px;
    }

    /* Print names table */
    .print-names-section h3 {
        font-size: 14px;
        color: var(--monogram-form-cyan-dark);
        margin-bottom: 10px;
    }

    .print-names-table {
        width: 100%;
        border-collapse: collapse;
        font-size: 11px;
    }

    .print-names-table th {
        background: var(--monogram-form-cyan-dark);
        color: white;
        padding: 8px 6px;
        text-align: left;
        font-weight: 600;
    }

    .print-names-table td {
        padding: 6px;
        border-bottom: 1px solid var(--store-line);
    }

    .print-names-table tbody tr:nth-child(even) {
        background: var(--gray-50);
    }

    /* Page breaks */
    .print-names-table {
        break-inside: auto;
    }

    .print-names-table tr {
        break-inside: avoid;
        break-after: auto;
    }

    .print-footer {
        position: fixed;
        bottom: 20px;
        right: 20px;
        font-size: 10px;
        color: var(--print-line);
    }
}

/* ============================================
   RESPONSIVE DESIGN
   ============================================ */
@media (width <= 768px) {
    .header-container {
        flex-direction: column;
        gap: 1rem;
        padding: 1rem;
    }

    .header-left {
        width: 100%;
        justify-content: space-between;
    }

    .breadcrumb {
        display: none;
    }

    .main-container {
        padding: 1rem;
    }

    .page-header {
        flex-direction: column;
        gap: 1rem;
        text-align: center;
    }

    .page-title {
        font-size: 1.5rem;
    }

    .form-row {
        grid-template-columns: 1fr;
    }

    .form-actions {
        flex-direction: column;
        gap: 1rem;
    }

    .actions-left,
    .actions-right {
        width: 100%;
        justify-content: center;
    }

    .section-header-row {
        flex-direction: column;
        gap: 1rem;
        align-items: flex-start;
    }

    .search-inputs {
        flex-direction: column;
    }

    .search-field {
        width: 100%;
    }
}

/* ============================================
   STITCH CHECK PANEL (live name QA)
   ============================================ */
.stitch-check-panel {
    margin-top: 1rem;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--card-bg);
    overflow: hidden;
}

.stitch-check-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.65rem 1rem;
    background: var(--hover-bg);
    border-bottom: 1px solid var(--border-color);
}

.stitch-check-header strong {
    color: var(--text-primary);
}

.stitch-check-header strong i {
    color: var(--primary-color);
    margin-right: 0.35rem;
}

.stitch-check-summary {
    font-size: 0.85rem;
    color: var(--text-secondary);
}

.stitch-check-summary.all-clear {
    color: var(--success-text);
    font-weight: 600;
}

.stitch-check-list {
    list-style: none;
    margin: 0;
    padding: 0.35rem 0;
}

.stitch-finding {
    display: flex;
    align-items: baseline;
    gap: 0.6rem;
    padding: 0.45rem 1rem;
    font-size: 0.875rem;
    cursor: pointer;
}

.stitch-finding:hover {
    background: var(--hover-bg);
}

.stitch-finding .finding-icon {
    flex: 0 0 auto;
}

.stitch-finding.severity-error .finding-icon { color: var(--error-text); }
.stitch-finding.severity-warn  .finding-icon { color: var(--warning-text); }
.stitch-finding.severity-info  .finding-icon { color: var(--text-secondary); }

.stitch-finding .finding-message {
    flex: 1 1 auto;
    color: var(--text-primary);
}

.stitch-finding .btn-fix-finding {
    flex: 0 0 auto;
    border: 1px solid var(--primary-color);
    background: var(--card-bg);
    color: var(--primary-color);
    border-radius: 4px;
    padding: 0.1rem 0.6rem;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
}

.stitch-finding .btn-fix-finding:hover {
    background: var(--primary-color);
    color: var(--color-on-brand);
}

/* Row highlight when a finding is clicked */
@keyframes qa-flash-fade {
    0%   { background-color: var(--warning-bg); }
    100% { background-color: transparent; }
}

.names-table tr.qa-flash > td {
    animation: qa-flash-fade 2s ease-out;
}

/* ============================================
   PRODUCTION PRINT — RUN PLAN + THREAD GROUPS
   ============================================ */
.print-run-plan {
    margin-top: 0.5rem;
    padding: 0.4rem 0.6rem;
    border: 1px solid var(--monogram-form-gray-dark);
    font-weight: 600;
    font-size: 10pt;
}

.print-names-table tr.thread-change-row td {
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    background: var(--monogram-form-gray-dark) !important;
    /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
    color: var(--color-on-brand) !important;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: 0.3rem 0.6rem;
    -webkit-print-color-adjust: exact;
}

/* Never let a thread-change banner orphan at the foot of a page — the
   operator would start a group with no visible cone instruction. */
.print-names-table tr.thread-change-row {
    break-after: avoid;
}

/* ============================================
   CUSTOMER PROOF SHEET
   ============================================ */
.proof-instructions {
    margin: 0.75rem 0 1rem;
    padding: 0.6rem 0.8rem;
    border: 1px solid var(--monogram-form-gray-dark);
    font-size: 10pt;
    line-height: 1.5;
}

/* Shown only when the Caspio thread-color library failed to load, so the
   printed colors are palette approximations rather than the real threads. */
.proof-color-notice {
    margin: 0 0 1rem;
    padding: 0.5rem 0.8rem;
    border: 1.5pt solid var(--monogram-form-gray-dark);
    font-size: 9.5pt;
    font-weight: 700;
}

.proof-list {
    display: block;
}

.proof-item {
    display: flex;
    align-items: center;
    gap: 0.9rem;
    padding: 0.55rem 0.25rem;
    border-bottom: 1px solid var(--gray-300);
    break-inside: avoid;
}

.proof-checkbox {
    flex: 0 0 auto;
    width: 16pt;
    height: 16pt;
    border: 1.5pt solid var(--monogram-form-gray-dark);
    display: inline-block;
}

.proof-name {
    flex: 1 1 auto;
    font-size: 22pt;
    line-height: 1.25;
    -webkit-print-color-adjust: exact;
}

/* White/pale thread on white paper: show the name on a dark chip so it stays
   legible while keeping the true thread color (set via isLightHex()).
   flex + fit-content keeps the chip hugging the name — .proof-name's
   `flex: 1 1 auto` would otherwise stretch it into a full-width bar. */
.proof-name-light {
    background: var(--store-ink-soft);
    border-radius: 4px;
    padding: 0 0.5rem;
    flex: 0 1 auto;
    width: fit-content;
    max-width: 100%;
    -webkit-print-color-adjust: exact;
}

.proof-meta {
    flex: 0 0 38%;
    font-size: 8.5pt;
    color: var(--monogram-form-gray-dark-2);
    line-height: 1.4;
    text-align: right;
}

.proof-meta .proof-meta-thread {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
}

.proof-swatch {
    display: inline-block;
    width: 8pt;
    height: 8pt;
    border: 0.5pt solid var(--monogram-form-gray-dark);
    -webkit-print-color-adjust: exact;
}

.proof-signoff {
    display: flex;
    gap: 2rem;
    margin-top: 2.5rem;
    break-inside: avoid;
}

.proof-signoff-line {
    flex: 1 1 auto;
    border-top: 1.5pt solid var(--monogram-form-gray-dark);
    padding-top: 0.3rem;
    font-size: 9pt;
}

.proof-signoff-date {
    flex: 0 0 20%;
}

/* Only one template prints at a time, chosen by a body class set in
   printProof()/afterprint (monogram-form-controller.js). */
@media print {
    body:not(.print-mode-proof) #proofTemplate {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        display: none !important;
    }

    body.print-mode-proof #printTemplate {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        display: none !important;
    }
}
